      function presentar(resumen) {
        const bruto = String(resumen || "").trim();
        if (!bruto) return "";
        const gritado = bruto === bruto.toUpperCase() && /[A-ZÁÉÍÓÚÑ]/.test(bruto);
        const palabras = bruto.split(/\s+/).map((palabra, i) => {
          const limpio = normalizar(palabra).replace(/[.,;:()]/g, "");
          if (UNIDADES_TEXTO[limpio]) return UNIDADES_TEXTO[limpio];
          if (/\d/.test(palabra)) {
            return gritado ? palabra.replace(/(\d)X(\d)/g, "$1x$2").replace(/KV\b/g, "kV").replace(/KW\b/g, "kW").replace(/MM\b/g, "mm").replace(/CV\b/g, "CV") : palabra;
          }
          if (SIGLAS.has(limpio)) return palabra.toUpperCase();
          const baja = gritado ? palabra.toLowerCase() : palabra;
          const sinTilde = normalizar(baja).replace(/[.,;:()]/g, "");
          if (CON_TILDE[sinTilde]) {
            const acentuada = CON_TILDE[sinTilde];
            return baja === baja.toLowerCase() ? acentuada : acentuada[0].toUpperCase() + acentuada.slice(1);
          }
          if (i === 0 && !gritado && /^[A-ZÁÉÍÓÚÑ][a-záéíóúñ]/.test(palabra)) {
            return palabra[0].toLowerCase() + palabra.slice(1);
          }
          return baja;
        });
        const texto = palabras.join(" ");
        return texto[0] === texto[0].toUpperCase() && /^[A-ZÁÉÍÓÚÑ][a-záéíóúñ]/.test(texto) ? texto[0].toLowerCase() + texto.slice(1) : texto;
      }
